import{_ as l}from"./chunks/ScenarioFitAssessment.CuCMhGwF.js";import{o as i,c as e,j as a,a as s,E as r,a3 as o}from"./chunks/framework.BPaanrMb.js";const m=JSON.parse('{"title":"自动驾驶场景适配判断","description":"通过运输需求、线路、车辆与货物、安全合规和经济性五道关卡，判断短途运输场景是否值得进入现场评估。","frontmatter":{"title":"自动驾驶场景适配判断","description":"通过运输需求、线路、车辆与货物、安全合规和经济性五道关卡，判断短途运输场景是否值得进入现场评估。","status":"设计建议","content_type":"assessment","keywords":["场景评估","自动驾驶适配","固定路线","安全合规","经济性","试点"],"scope":"企业短途自动驾驶运输项目的初步适用性筛选","decision_summary":"五道关卡全部回答后，工具会给出“进入现场评估、补齐信息或当前不建议部署”的本地结论。","best_for":["高频固定线路","明确运营主体","可管理场地","可估算运营成本"],"not_for":["合规责任未落实","低频偶发运输","无明确负责人和预算","仅做无人驾驶展示"],"next_action":"完成五步判断，打印或复制摘要，再决定是否开展现场调研。","cta_url":"mailto:support@wheelos.cn?subject=WheelOS%20scenario%20fit%20assessment","layout":"doc","sidebar":false,"aside":false,"outline":[2,3]},"headers":[],"relativePath":"solutions/fit-assessment.md","filePath":"solutions/fit-assessment.md","lastUpdated":1794551845000}'),d={name:"solutions/fit-assessment.md"},b=Object.assign(d,{setup(n){return(h,t)=>(i(),e("div",null,[t[0]||(t[0]=a("h1",{id:"自动驾驶场景适配判断",tabindex:"-1"},[s("自动驾驶场景适配判断 "),a("a",{class:"header-anchor",href:"#自动驾驶场景适配判断","aria-label":'Permalink to "自动驾驶场景适配判断"'},"​")],-1)),t[1]||(t[1]=a("blockquote",null,[a("p",null,"先判断任务是否值得做，再选择车辆和系统。这个工具只在浏览器本地计算，不会上传答案。")],-1)),r(l),t[2]||(t[2]=o('<h2 id="静态判断摘要" tabindex="-1">静态判断摘要 <a class="header-anchor" href="#静态判断摘要" aria-label="Permalink to &quot;静态判断摘要&quot;">​</a></h2><p>即使不使用交互工具，也可以先检查以下五类条件：</p><table tabindex="0"><thead><tr><th>关卡</th><th>核心问题</th><th>判断影响</th></tr></thead><tbody><tr><td>运输需求</td><td>是否长期、重复、频次稳定，并持续投入司机或车辆？</td><td>低频偶发任务通常难以形成经济性</td></tr><tr><td>线路条件</td><td>起终点、通道、装卸区和交接方式是否明确、可管理？</td><td>复杂混行和不确定交接会增加项目风险</td></tr><tr><td>车辆与货物</td><td>重量、尺寸、温控、装卸和业务系统接口是否明确？</td><td>非标准货物需要额外的车辆或作业方案</td></tr><tr><td>安全与合规</td><td>准入、许可、安全责任、保险和异常处理是否落实？</td><td>关键责任未落实时，不应进入商业部署</td></tr><tr><td>经济性</td><td>当前成本、完整投入和每日有效任务量是否可估算？</td><td>需要与现有运输方式比较，而不是只看自动驾驶功能</td></tr></tbody></table><h2 id="完整判断清单" tabindex="-1">完整判断清单 <a class="header-anchor" href="#完整判断清单" aria-label="Permalink to &quot;完整判断清单&quot;">​</a></h2><h3 id="运输需求" tabindex="-1">运输需求 <a class="header-anchor" href="#运输需求" aria-label="Permalink to &quot;运输需求&quot;">​</a></h3><ul><li>[ ] 运输任务长期存在，不属于偶发需求。</li><li>[ ] 每天或每周有相对稳定的运输频次。</li><li>[ ] 起点、终点和主要运输任务较明确。</li><li>[ ] 当前持续投入司机、车辆或调度资源。</li></ul><h3 id="线路条件" tabindex="-1">线路条件 <a class="header-anchor" href="#线路条件" aria-label="Permalink to &quot;线路条件&quot;">​</a></h3><ul><li>[ ] 线路相对固定，起终点明确。</li><li>[ ] 道路和作业区域具备车辆通行条件。</li><li>[ ] 装卸与交接位置相对固定。</li><li>[ ] 人车混行、路口和临时障碍可评估、可管理。</li></ul><h3 id="车辆与货物" tabindex="-1">车辆与货物 <a class="header-anchor" href="#车辆与货物" aria-label="Permalink to &quot;车辆与货物&quot;">​</a></h3><ul><li>[ ] 货物重量、尺寸和运输要求明确。</li><li>[ ] 车辆载荷和货厢空间满足需求。</li><li>[ ] 温控、保温、密封等要求已经明确并有对应方案。</li><li>[ ] 装卸流程和交接方式可以标准化。</li><li>[ ] 仓储、调度等业务系统是否需要对接已经明确。</li></ul><h3 id="安全与合规" tabindex="-1">安全与合规 <a class="header-anchor" href="#安全与合规" aria-label="Permalink to &quot;安全与合规&quot;">​</a></h3><ul><li>[ ] 车辆运行区域和准入要求已经明确。</li><li>[ ] 运营许可、场地管理和安全责任可以落实。</li><li>[ ] 异常处理、紧急停车和现场响应机制可以落实。</li><li>[ ] 保险和事故责任安排明确。</li><li>[ ] 特殊货物运输要求能够满足，或能够明确排除。</li></ul><h3 id="经济性" tabindex="-1">经济性 <a class="header-anchor" href="#经济性" aria-label="Permalink to &quot;经济性&quot;">​</a></h3><ul><li>[ ] 已了解当前司机、车辆和运输服务成本。</li><li>[ ] 可估算车辆、系统、部署、维护和运营成本。</li><li>[ ] 每日有效运输任务量能够支撑投入。</li><li>[ ] 有明确业务负责人、预算和合作意愿。</li></ul><h2 id="常见的不建议部署情况" tabindex="-1">常见的不建议部署情况 <a class="header-anchor" href="#常见的不建议部署情况" aria-label="Permalink to &quot;常见的不建议部署情况&quot;">​</a></h2><ul><li>任务只是短期展示，无法形成稳定利用率。</li><li>没有明确运营主体、预算和长期计划。</li><li>线路、装卸和交接流程高度不确定。</li><li>法规、保险或安全责任尚未落实。</li><li>特殊货物要求无法满足，也没有备选方案。</li><li>客户只关注“无人驾驶”，没有业务指标。</li></ul><h2 id="评估之后" tabindex="-1">评估之后 <a class="header-anchor" href="#评估之后" aria-label="Permalink to &quot;评估之后&quot;">​</a></h2><ul><li><strong>建议进入现场评估：</strong> 继续核对车辆、底盘、路线、场地和验收指标。</li><li><strong>信息不足：</strong> 先补齐关键数据，不急于采购车辆。</li><li><strong>当前不建议部署：</strong> 先解决需求、线路、安全责任或经济性问题。</li></ul><p><a href="/solutions/delivery-process">查看从需求沟通到试点部署的流程 →</a></p><div class="solution-cta"><div><h2>需要一起看你的真实运输任务？</h2><p>发送货物、起终点、频次、车辆和当前的运输方式，我们会协助完成初步筛选。</p></div><div class="solution-actions"><a class="primary" href="mailto:support@wheelos.cn?subject=WheelOS%20scenario%20fit%20assessment">提交场景摘要</a><a href="/solutions/applications">查看六类应用场景</a></div></div>',20))]))}});export{m as __pageData,b as default};
